export type DepositNote = {
  version: 1;
  chainId: number;
  pool: string;
  secret: string;
  commitment: string;
  leafIndex?: number;
  createdAt: string;
};

export type DestinationChain = {
  label: string;
  domain: number;
  chainId?: number;
  isLocal?: boolean;
};

export const NOTE_PREFIX = "privatecrypmix-note-v1:";

export function encodeNote(note: DepositNote): string {
  return `${NOTE_PREFIX}${btoa(JSON.stringify(note))}`;
}

export function decodeNote(serialized: string): DepositNote {
  if (!serialized.startsWith(NOTE_PREFIX)) {
    throw new Error("Invalid PrivateCrypMix note prefix");
  }

  const encoded = serialized.slice(NOTE_PREFIX.length);
  const note = JSON.parse(atob(encoded)) as DepositNote;

  if (note.version !== 1 || !note.secret || !note.commitment || !note.pool) {
    throw new Error("Malformed PrivateCrypMix note");
  }

  return note;
}
```

