// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Lightweight incremental Merkle tree for development/reference use.
/// @dev Hashing uses keccak256. Production circuit and contract hashing must match exactly.
library MerkleTree {
    uint32 internal constant ROOT_HISTORY_SIZE = 100;

    struct Tree {
        uint32 levels;
        uint32 nextIndex;
        bytes32 currentRoot;
        mapping(uint32 => bytes32) zeros;
        mapping(uint32 => bytes32) filledSubtrees;
        mapping(uint32 => bytes32) roots;
        uint32 currentRootIndex;
    }

    error TreeIsFull();
    error InvalidLevels();

    function init(Tree storage self, uint32 levels, bytes32 zeroValue) internal {
        if (levels == 0 || levels > 32) revert InvalidLevels();

        self.levels = levels;

        bytes32 currentZero = zeroValue;
        for (uint32 i = 0; i < levels; i++) {
            self.zeros[i] = currentZero;
            self.filledSubtrees[i] = currentZero;
            currentZero = hashLeftRight(currentZero, currentZero);
        }

        self.currentRoot = currentZero;
        self.roots[0] = currentZero;
    }

    function insert(Tree storage self, bytes32 leaf) internal returns (uint32 index) {
        uint32 maxLeaves = uint32(1) << self.levels;
        if (self.nextIndex >= maxLeaves) revert TreeIsFull();

        index = self.nextIndex;
        uint32 currentIndex = index;
        bytes32 currentLevelHash = leaf;

        for (uint32 i = 0; i < self.levels; i++) {
            if (currentIndex % 2 == 0) {
                self.filledSubtrees[i] = currentLevelHash;
                currentLevelHash = hashLeftRight(currentLevelHash, self.zeros[i]);
            } else {
                currentLevelHash = hashLeftRight(self.filledSubtrees[i], currentLevelHash);
            }

            currentIndex /= 2;
        }

        self.currentRootIndex = (self.currentRootIndex + 1) % ROOT_HISTORY_SIZE;
        self.currentRoot = currentLevelHash;
        self.roots[self.currentRootIndex] = currentLevelHash;
        self.nextIndex = index + 1;
    }

    function isKnownRoot(Tree storage self, bytes32 root) internal view returns (bool) {
        if (root == bytes32(0)) return false;

        uint32 index = self.currentRootIndex;
        do {
            if (self.roots[index] == root) return true;

            if (index == 0) {
                index = ROOT_HISTORY_SIZE - 1;
            } else {
                index -= 1;
            }
        } while (index != self.currentRootIndex);

        return false;
    }

    function hashLeftRight(bytes32 left, bytes32 right) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(left, right));
    }
}
```

## `contracts/contracts/adapters/AaveYieldAdapter.sol`

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IAavePool} from "../interfaces/IAavePool.sol";

/// @notice Holds the pool's Aave position.
/// @dev The mixer contract is the only authorized caller for supply/withdraw.
contract AaveYieldAdapter is Ownable {
    using SafeERC20 for IERC20;

    error NotMixer();
    error InvalidAddress();

    IERC20 public immutable asset;
    IERC20 public immutable aToken;
    IAavePool public immutable aavePool;
    address public mixer;

    event MixerUpdated(address indexed mixer);
    event Supplied(uint256 amount);
    event Withdrawn(address indexed recipient, uint256 amount);

    constructor(
        address initialOwner,
        address asset_,
        address aToken_,
        address aavePool_
    ) Ownable(initialOwner) {
        if (asset_ == address(0) || aToken_ == address(0) || aavePool_ == address(0)) {
            revert InvalidAddress();
        }

        asset = IERC20(asset_);
        aToken = IERC20(aToken_);
        aavePool = IAavePool(aavePool_);
    }

    modifier onlyMixer() {
        if (msg.sender != mixer) revert NotMixer();
        _;
    }

    function setMixer(address mixer_) external onlyOwner {
        if (mixer_ == address(0)) revert InvalidAddress();
        mixer = mixer_;
        emit MixerUpdated(mixer_);
    }

    function supply(uint256 amount) external onlyMixer {
        asset.forceApprove(address(aavePool), amount);
        aavePool.supply(address(asset), amount, address(this), 0);
        emit Supplied(amount);
    }

    function withdrawTo(address recipient, uint256 amount) external onlyMixer returns (uint256) {
        uint256 withdrawn = aavePool.withdraw(address(asset), amount, recipient);
        emit Withdrawn(recipient, withdrawn);
        return withdrawn;
    }

    function positionValue() external view returns (uint256) {
        return aToken.balanceOf(address(this));
    }
}
```

