// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IConnext} from "../interfaces/IConnext.sol";

/// @notice Adapter for a Connext-compatible xcall deployment.
/// @dev Production bridging requires destination-specific configuration and testing.
contract ConnextBridgeAdapter is Ownable {
    using SafeERC20 for IERC20;

    error NotMixer();
    error InvalidAddress();

    IConnext public immutable connext;
    address public mixer;

    event MixerUpdated(address indexed mixer);
    event XCallInitiated(
        bytes32 indexed transferId,
        uint32 indexed destinationDomain,
        address indexed recipient,
        address asset,
        uint256 amount
    );

    constructor(address initialOwner, address connext_) Ownable(initialOwner) {
        if (connext_ == address(0)) revert InvalidAddress();
        connext = IConnext(connext_);
    }

    modifier onlyMixer() {
        if (msg.sender != mixer) revert NotMixer();
        _;
    }

    function setMixer(address mixer_) external onlyOwner {
        if (mixer_ == address(0)) revert InvalidAddress();
        mixer = mixer_;
        emit MixerUpdated(mixer_);
    }

    function bridge(
        address asset,
        uint256 amount,
        uint32 destinationDomain,
        address recipient,
        uint256 slippage
    ) external payable onlyMixer returns (bytes32 transferId) {
        IERC20(asset).forceApprove(address(connext), amount);

        transferId = connext.xcall{value: msg.value}(
            destinationDomain,
            recipient,
            asset,
            address(this),
            amount,
            slippage,
            bytes("")
        );

        emit XCallInitiated(
            transferId,
            destinationDomain,
            recipient,
            asset,
            amount
        );
    }

    receive() external payable {}
}
