pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IVerifier} from "./interfaces/IVerifier.sol";
import {MerkleTree} from "./libraries/MerkleTree.sol";
import {AaveYieldAdapter} from "./adapters/AaveYieldAdapter.sol";
import {ConnextBridgeAdapter} from "./adapters/ConnextBridgeAdapter.sol";

/// @title PrivateCrypMix
/// @notice Fixed-denomination, timelocked commitment pool with yield and bridge adapters.
/// @dev Development reference implementation. Replace verifier before production use.
contract PrivateCrypMix is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using MerkleTree for MerkleTree.Tree;

    error InvalidAmount();
    error CommitmentAlreadyExists();
    error UnknownRoot();
    error NullifierAlreadySpent();
    error InvalidProof();
    error WithdrawalStillLocked(uint256 unlockTime);
    error InvalidRecipient();
    error UnsupportedDestination();
    error InsufficientPoolLiquidity();
    error InvalidFee();
    error BridgeFeeRequired();

    struct DepositInfo {
        uint64 depositedAt;
        uint32 leafIndex;
        bool exists;
    }

    struct WithdrawalRequest {
        bytes proof;
        bytes32 root;
        bytes32 nullifierHash;
        address recipient;
        uint32 destinationDomain;
        uint256 relayerFee;
        uint256 bridgeSlippage;
    }

    IERC20 public immutable asset;
    IVerifier public verifier;
    AaveYieldAdapter public immutable yieldAdapter;
    ConnextBridgeAdapter public immutable bridgeAdapter;

    uint256 public immutable denomination;
    uint256 public immutable minimumWithdrawalDelay;
    uint32 public immutable localDomain;

    uint256 public totalPrincipalDeposited;
    uint256 public totalWithdrawals;

    mapping(bytes32 => DepositInfo) public deposits;
    mapping(bytes32 => bool) public nullifierHashes;
    mapping(uint32 => bool) public supportedDestinationDomains;

    MerkleTree.Tree private tree;

    event Deposit(
        bytes32 indexed commitment,
        uint32 indexed leafIndex,
        uint256 amount,
        uint256 depositedAt,
        uint256 unlockTime
    );

    event Withdrawal(
        bytes32 indexed nullifierHash,
        address indexed recipient,
        uint32 indexed destinationDomain,
        uint256 amount,
        uint256 relayerFee,
        bytes32 bridgeTransferId
    );

    event DestinationUpdated(uint32 indexed domain, bool supported);
    event VerifierUpdated(address indexed verifier);
    event EmergencyWithdraw(address indexed recipient, uint256 amount);

    constructor(
        address initialOwner,
        address asset_,
        address verifier_,
        address yieldAdapter_,
        address bridgeAdapter_,
        uint256 denomination_,
        uint256 minimumWithdrawalDelay_,
        uint32 localDomain_,
        uint32 merkleTreeLevels,
        bytes32 zeroValue
    ) Ownable(initialOwner) {
        require(asset_ != address(0), "asset=0");
        require(verifier_ != address(0), "verifier=0");
        require(yieldAdapter_ != address(0), "yieldAdapter=0");
        require(bridgeAdapter_ != address(0), "bridgeAdapter=0");
        require(denomination_ > 0, "denomination=0");
        require(minimumWithdrawalDelay_ > 0, "delay=0");

        asset = IERC20(asset_);
        verifier = IVerifier(verifier_);
        yieldAdapter = AaveYieldAdapter(yieldAdapter_);
        bridgeAdapter = ConnextBridgeAdapter(payable(bridgeAdapter_));

        denomination = denomination_;
        minimumWithdrawalDelay = minimumWithdrawalDelay_;
        localDomain = localDomain_;

        tree.init(merkleTreeLevels, zeroValue);
        supportedDestinationDomains[localDomain_] = true;
    }

    function deposit(bytes32 commitment) external whenNotPaused nonReentrant {
        if (deposits[commitment].exists) revert CommitmentAlreadyExists();

        asset.safeTransferFrom(msg.sender, address(this), denomination);
        asset.forceApprove(address(yieldAdapter), denomination);
        asset.safeTransfer(address(yieldAdapter), denomination);

        yieldAdapter.supply(denomination);

        uint32 leafIndex = tree.insert(commitment);
        uint64 depositedAt = uint64(block.timestamp);

        deposits[commitment] = DepositInfo({
            depositedAt: depositedAt,
            leafIndex: leafIndex,
            exists: true
        });

        totalPrincipalDeposited += denomination;

        emit Deposit(
            commitment,
            leafIndex,
            denomination,
            depositedAt,
            uint256(depositedAt) + minimumWithdrawalDelay
        );
    }

    function withdraw(
        WithdrawalRequest calldata request
    ) external payable whenNotPaused nonReentrant returns (bytes32 bridgeTransferId) {
        if (request.recipient == address(0)) revert InvalidRecipient();
        if (!supportedDestinationDomains[request.destinationDomain]) {
            revert UnsupportedDestination();
        }
        if (nullifierHashes[request.nullifierHash]) revert NullifierAlreadySpent();
        if (!tree.isKnownRoot(request.root)) revert UnknownRoot();

        if (
            !verifier.verifyProof(
                request.proof,
                request.root,
                request.nullifierHash,
                request.recipient,
                request.destinationDomain,
                request.relayerFee
            )
        ) {
            revert InvalidProof();
        }

        /*
         * The proof proves membership, but a production circuit should additionally
         * expose or bind deposit-time data needed to prove lock maturity without
         * revealing the leaf. This reference implementation conservatively uses
         * the pool creation/deposit maturity policy at an operational level.
         *
         * For a production system, include a timestamp commitment / epoch mechanism
         * in the circuit and public inputs.
         */
        uint256 earliestAllowed = _poolEarliestWithdrawalTime();
        if (block.timestamp < earliestAllowed) {
            revert WithdrawalStillLocked(earliestAllowed);
        }

        nullifierHashes[request.nullifierHash] = true;

        uint256 available = yieldAdapter.positionValue();
        if (available < denomination) revert InsufficientPoolLiquidity();

        uint256 grossAmount = denomination;
        uint256 distributableYield = available > totalPrincipalOutstanding()
            ? available - totalPrincipalOutstanding()
            : 0;

        /*
         * Reference policy: distribute all currently observable yield to each
         * withdrawal only up to the pool's available balance. Production systems
         * need an auditable, mathematically specified yield allocation mechanism.
         */
        uint256 yieldShare = distributableYield > 0
            ? distributableYield / _remainingDepositsEstimate()
            : 0;

        grossAmount += yieldShare;

        if (request.relayerFee > grossAmount) revert InvalidFee();

        uint256 recipientAmount = grossAmount - request.relayerFee;

        if (request.destinationDomain == localDomain) {
            yieldAdapter.withdrawTo(request.recipient, recipientAmount);

            if (request.relayerFee > 0) {
                yieldAdapter.withdrawTo(msg.sender, request.relayerFee);
            }
        } else {
            if (msg.value == 0) revert BridgeFeeRequired();

            yieldAdapter.withdrawTo(address(this), recipientAmount);
            asset.forceApprove(address(bridgeAdapter), recipientAmount);

            bridgeTransferId = bridgeAdapter.bridge{value: msg.value}(
                address(asset),
                recipientAmount,
                request.destinationDomain,
                request.recipient,
                request.bridgeSlippage
            );

            if (request.relayerFee > 0) {
                yieldAdapter.withdrawTo(msg.sender, request.relayerFee);
            }
        }

        totalWithdrawals += denomination;

        emit Withdrawal(
            request.nullifierHash,
            request.recipient,
            request.destinationDomain,
            grossAmount,
            request.relayerFee,
            bridgeTransferId
        );
    }

    function setDestinationDomain(uint32 domain, bool supported) external onlyOwner {
        supportedDestinationDomains[domain] = supported;
        emit DestinationUpdated(domain, supported);
    }

    function setVerifier(address verifier_) external onlyOwner {
        require(verifier_ != address(0), "verifier=0");
        verifier = IVerifier(verifier_);
        emit VerifierUpdated(verifier_);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /// @notice Emergency-only recovery for assets accidentally held by this contract.
    /// @dev Does not withdraw assets held in the yield adapter.
    function emergencyWithdrawDirectAsset(address recipient, uint256 amount) external onlyOwner {
        asset.safeTransfer(recipient, amount);
        emit EmergencyWithdraw(recipient, amount);
    }

    function currentRoot() external view returns (bytes32) {
        return tree.currentRoot;
    }

    function nextLeafIndex() external view returns (uint32) {
        return tree.nextIndex;
    }

    function isKnownRoot(bytes32 root) external view returns (bool) {
        return tree.isKnownRoot(root);
    }

    function totalPrincipalOutstanding() public view returns (uint256) {
        return totalPrincipalDeposited - totalWithdrawals;
    }

    function _poolEarliestWithdrawalTime() internal view returns (uint256) {
        /*
         * Reference-only global timelock. Production circuit must enforce
         * individual deposit maturity privately through a timestamp/epoch witness.
         */
        return minimumWithdrawalDelay;
    }

    function _remainingDepositsEstimate() internal view returns (uint256) {
        uint256 outstanding = totalPrincipalOutstanding();
        if (outstanding == 0) return 1;

        uint256 remaining = outstanding / denomination;
        return remaining == 0 ? 1 : remaining;
    }

    receive() external payable {}
}
```

> **Required production correction:** The `PrivateCrypMix` contract above demonstrates the interfaces and state model, but the `_poolEarliestWithdrawalTime()` implementation must be replaced with a privacy-preserving per-note lock mechanism enforced in the zk circuit. A simplistic global timestamp cannot correctly prove an individual hidden deposit’s maturity.

A safer reference replacement is to define fixed deposit epochs. Each epoch has a Merkle tree and a public `withdrawalStart` timestamp. A withdrawal proof proves membership in the selected epoch tree, and the contract checks that epoch’s public unlock time.

